// ======================= PREENCHA AQUI =======================
const config = {
  // Chat do Telegram que recebe avisos e pedidos de aprovação.
  chat_id: '-1001234567890',
  // URL do smokeping-manager (usada para ver se o link continua ruim antes de escalar).
  manager_url: 'https://manager-ping.exemplo.com.br',
  // Minutos entre uma ação aplicada e a checagem para sugerir o próximo degrau.
  espera_escalada_min: 5,
  // Roteador (nome no manager) -> AS local e, por link (nome no manager), o peer BGP
  // e as route-policies de export que já existem no roteador.
  mapa: {
    ne8k: {
      bgp_as: 65000,
      links: {
        'isp-a': {
          peer: '192.0.2.254',
          vpn_instance: 'upstream-1', // vazio = tabela global (ipv4-family unicast)
          politica_normal: 'RP-ISP-A-OUT',
          politica_community: 'RP-ISP-A-OUT-COMMUNITY',
          politica_prepend: 'RP-ISP-A-OUT-PREPEND',
          politica_bloqueio: 'RP-DENY-ALL',
        },
        'isp-b': {
          peer: '198.51.100.254',
          vpn_instance: '',
          politica_normal: 'RP-ISP-B-OUT',
          politica_community: 'RP-ISP-B-OUT-COMMUNITY',
          politica_prepend: 'RP-ISP-B-OUT-PREPEND',
          politica_bloqueio: 'RP-DENY-ALL',
        },
      },
    },
  },
};
// =============================================================
return $input.all().map(item => ({ json: { ...item.json, ...config } }));

// Junta o alerta, o mapeamento do link e o degrau já aplicado; monta o pedido para a LLM (DeepSeek).
const DEGRAUS = ['nenhuma', 'community', 'prepend', 'retirar_anuncio', 'desativar_peer'];
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
const cfgGeral = $('Configuração').first().json;
const p = $json.body;
const estado = $getWorkflowStaticData('global');
estado.incidentes = estado.incidentes || {};

const link = p.probe?.link?.name || '';
const roteador = p.probe?.router?.name || '';
const chave = `${p.target.id}|${link || 'local'}`;
const atual = estado.incidentes[chave]?.degrau || 0;
const saudaveis = (p.all_series || []).filter(s => s.link && s.link !== link && !s.failing).map(s => s.link);
const perda = p.metrics?.loss_percent;
const titulo = `${p.target.title} (${p.target.host})`;
const base = { chave, payload: p, roteador, link, degrau_atual: atual, links_saudaveis: saudaveis };

if (p.probe?.type !== 'remote') {
  return { json: { ...base, pular: true, aviso: `ℹ️ Perda alta no ping local de <b>${esc(titulo)}</b>: ${perda}%.\nNão há link BGP associado, nada a mitigar.` } };
}
const rot = cfgGeral.mapa?.[roteador];
const cfg = rot?.links?.[link];
if (!cfg) {
  return { json: { ...base, pular: true, aviso: `⚠️ Perda de ${perda}% em <b>${esc(titulo)}</b> via ${esc(roteador)}/${esc(link)}, mas esse link não está no mapa do nó Configuração.` } };
}
if (atual >= DEGRAUS.length - 1) {
  return { json: { ...base, pular: true, aviso: `⚠️ <b>${esc(titulo)}</b> via ${esc(link)} continua com ${perda}% de perda e o peer já está desativado. Intervenção manual.` } };
}

const system = `Você é um engenheiro de redes de plantão num provedor com roteador Huawei NE8000.
Você recebe um alerta de perda de pacotes medida por ping remoto a partir de um link de trânsito (cada link é uma sessão BGP com um upstream) e escolhe a próxima ação de mitigação. Um operador humano aprova ou rejeita a ação antes de ela ser aplicada.

Degraus, do mais leve ao mais pesado:
1. community: exporta com uma community que pede ao upstream para reduzir a preferência das nossas rotas.
2. prepend: exporta com AS-path prepend, desviando parte do tráfego de entrada.
3. retirar_anuncio: deixa de anunciar nossos prefixos por esse link.
4. desativar_peer: derruba a sessão BGP com o upstream (peer ignore).

Regras:
- Escolha "nenhuma" ou exatamente o próximo degrau informado em proximo_degrau.
- Se todos os links mostram perda parecida, o problema provavelmente é o destino ou algo em comum: escolha "nenhuma".
- Nunca escolha retirar_anuncio ou desativar_peer se links_saudaveis estiver vazio.
- Perda perto do limite ou só num destino isolado favorece "nenhuma" ou um degrau leve.
- O motivo vai para o operador no Telegram: português, no máximo 3 frases, citando os números que pesaram.

Responda só com um objeto json neste formato:
{"acao": "nenhuma|community|prepend|retirar_anuncio|desativar_peer", "motivo": "texto", "risco": "baixo|medio|alto", "diagnostico": "link|destino|incerto"}`;

const entrada = {
  degrau_atual: DEGRAUS[atual],
  proximo_degrau: DEGRAUS[atual + 1],
  links_saudaveis: saudaveis,
  alerta: p,
};

// DeepSeek só garante JSON válido (json_object), não o schema: decidir.js valida os campos.
const llm_request = {
  model: 'deepseek-flash',
  max_tokens: 1000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify(entrada, null, 2) },
  ],
};

return { json: { ...base, pular: false, cfg: { ...cfg, bgp_as: rot.bgp_as }, llm_request } };

// Lê a resposta da LLM, aplica as travas de segurança e gera os comandos VRP.
const DEGRAUS = ['nenhuma', 'community', 'prepend', 'retirar_anuncio', 'desativar_peer'];
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
const ctx = $('Preparar contexto').item.json;
const r = $json;
const p = ctx.payload;
const titulo = `${p.target.title} (${p.target.host})`;

const falha = motivo => ({ acao: 'nenhuma', motivo, risco: 'alto', diagnostico: 'incerto' });
const conteudo = r.choices?.[0]?.message?.content?.trim();
let decisao;
if (!conteudo) {
  // DeepSeek devolve conteúdo em branco quando não consegue gerar JSON válido.
  decisao = falha('A LLM devolveu resposta vazia.');
} else {
  try {
    decisao = JSON.parse(conteudo);
  } catch (e) {
    decisao = falha(`Resposta inválida da LLM: ${e.message}`);
  }
}
if (!decisao || typeof decisao !== 'object') decisao = falha('A LLM não devolveu um objeto JSON.');
decisao.motivo = String(decisao.motivo || 'sem motivo informado');
if (!['baixo', 'medio', 'alto'].includes(decisao.risco)) decisao.risco = 'alto';
if (!['link', 'destino', 'incerto'].includes(decisao.diagnostico)) decisao.diagnostico = 'incerto';

const notas = [];
let degrau = DEGRAUS.indexOf(decisao.acao);
if (degrau < 0) degrau = 0;
if (degrau > ctx.degrau_atual + 1) {
  degrau = ctx.degrau_atual + 1;
  notas.push('A LLM sugeriu pular degraus; limitado ao próximo.');
} else if (degrau > 0 && degrau <= ctx.degrau_atual) {
  degrau = 0;
  notas.push('Esse degrau já está aplicado.');
}
if (degrau >= 3 && !ctx.links_saudaveis.length) {
  degrau = 0;
  notas.push('Bloqueado: não há outro link saudável.');
}
const acao = DEGRAUS[degrau];

const c = ctx.cfg;
const familia = c.vpn_instance ? `ipv4-family vpn-instance ${c.vpn_instance}` : 'ipv4-family unicast';
const exportar = politica => [`bgp ${c.bgp_as}`, familia, `peer ${c.peer} route-policy ${politica} export`];
const comandos = {
  community: exportar(c.politica_community),
  prepend: exportar(c.politica_prepend),
  retirar_anuncio: exportar(c.politica_bloqueio),
  desativar_peer: [`bgp ${c.bgp_as}`, ...(c.vpn_instance ? [familia] : []), `peer ${c.peer} ignore`],
}[acao] || [];

const resumo = `${titulo} via ${ctx.roteador}/${ctx.link}`;
const perdas = (p.all_series || []).map(s => `${s.link || 'local'}: ${s.loss_percent}%${s.failing ? ' (falhando)' : ''}`).join(', ');

if (acao === 'nenhuma') {
  return { json: { ...ctx, acao, degrau, tem_acao: false, aviso:
    `🔎 Perda alta em <b>${esc(resumo)}</b> (${p.metrics?.loss_percent}%).\n` +
    (decisao.acao === 'nenhuma' ? 'A LLM não recomenda mexer no BGP.\n' : `A LLM sugeriu ${esc(decisao.acao)}, mas a ação foi bloqueada.\n`) +
    `Diagnóstico: ${esc(decisao.diagnostico)}. ${esc(decisao.motivo)}` + (notas.length ? `\n${esc(notas.join(' '))}` : '') +
    `\nSéries: ${esc(perdas)}` } };
}

const texto = [
  `⚠️ Perda de ${p.metrics?.loss_percent}% em ${resumo}`,
  `Séries: ${perdas}`,
  `Degrau atual: ${DEGRAUS[ctx.degrau_atual]} → proposto: ${acao} (risco ${decisao.risco}, diagnóstico ${decisao.diagnostico})`,
  `Motivo: ${decisao.motivo}`,
  ...notas,
  '',
  'Comandos:',
  ...comandos,
  'commit',
].join('\n');

return { json: { ...ctx, acao, degrau, tem_acao: true, resumo, comandos,
  comandos_b64: Buffer.from(comandos.join('\n')).toString('base64'), texto } };

// Guarda o degrau aplicado (para escalar e para desfazer) e monta o aviso do resultado.
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
const d = $('Decidir ação').item.json;
const ok = $json.code === 0;
const estado = $getWorkflowStaticData('global');
estado.incidentes = estado.incidentes || {};
if (ok) {
  estado.incidentes[d.chave] = { degrau: d.degrau, roteador: d.roteador, link: d.link, cfg: d.cfg, titulo: d.payload.target.title, aplicado_em: new Date().toISOString() };
}
const saida = String($json.stderr || $json.stdout || $json.error?.message || $json.error || '').slice(-1500);
const aviso = ok
  ? `✅ Aplicado <b>${esc(d.acao)}</b> em ${esc(d.resumo)}.`
  : `❌ Falhou ao aplicar ${esc(d.acao)} em ${esc(d.resumo)}.\n<pre>${esc(saida)}</pre>`;
return { json: { ok, aviso, escalar: ok && d.degrau < 4, chave: d.chave, payload: d.payload } };

// Depois da espera: se o incidente ainda está aberto e o link continua ruim, volta para a LLM.
const r = $('Registrar aplicação').itemMatching(0).json;
const estado = $getWorkflowStaticData('global');
if (!estado.incidentes?.[r.chave]) return [];

const p = JSON.parse(JSON.stringify(r.payload));
const link = p.probe?.link?.name || '';
const alvo = ($input.first().json.targets || []).find(t => t.id === p.target.id);
if (!alvo?.metrics) return [];

const metricas = s => ({ loss_percent: s.loss, latency_ms: s.loss >= 100 ? null : s.latency, jitter_ms: s.loss >= 100 ? null : s.jitter, samples: s.samples });
const series = alvo.metrics.links || [];
const atual = link ? series.find(s => s.name === link) : alvo.metrics;
if (!atual || atual.loss == null || atual.loss < p.rule.loss_percent) return [];

p.event = 'escalada';
p.timestamp = new Date().toISOString();
p.metrics = metricas(atual);
for (const s of p.all_series || []) {
  const novo = s.link ? series.find(x => x.name === s.link) : (alvo.metrics.loss != null ? alvo.metrics : null);
  if (novo) Object.assign(s, metricas(novo), { failing: novo.loss >= p.rule.loss_percent });
}
return [{ json: { body: p } }];

// No recovered: se o workflow aplicou algo nesse link, monta os comandos para voltar ao normal.
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
const p = $json.body;
const link = p.probe?.link?.name || '';
const chave = `${p.target.id}|${link || 'local'}`;
const estado = $getWorkflowStaticData('global');
const st = estado.incidentes?.[chave];
const resumo = `${p.target.title} (${p.target.host})${link ? ` via ${p.probe.router.name}/${link}` : ''}`;

if (!st) {
  return { json: { chave, tem_estado: false, aviso: `✅ <b>${esc(resumo)}</b> recuperou (perda ${p.metrics?.loss_percent}%, ${p.incident?.duration_seconds}s de incidente). Nada foi aplicado pelo workflow.` } };
}
const c = st.cfg;
const familia = c.vpn_instance ? `ipv4-family vpn-instance ${c.vpn_instance}` : 'ipv4-family unicast';
const comandos = [`bgp ${c.bgp_as}`];
if (c.vpn_instance) comandos.push(familia);
if (st.degrau >= 4) comandos.push(`undo peer ${c.peer} ignore`);
if (!c.vpn_instance) comandos.push(familia);
comandos.push(`peer ${c.peer} route-policy ${c.politica_normal} export`);

const DEGRAUS = ['nenhuma', 'community', 'prepend', 'retirar_anuncio', 'desativar_peer'];
const texto = [
  `✅ ${resumo} recuperou: perda ${p.metrics?.loss_percent}%.`,
  `Aplicado pelo workflow: ${DEGRAUS[st.degrau]} (em ${st.aplicado_em}).`,
  'Desfazer com:',
  ...comandos,
  'commit',
].join('\n');
return { json: { chave, tem_estado: true, roteador: st.roteador, resumo, comandos,
  comandos_b64: Buffer.from(comandos.join('\n')).toString('base64'), texto } };

const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);
const d = $('Preparar desfazer').item.json;
const ok = $json.code === 0;
if (ok) delete $getWorkflowStaticData('global').incidentes[d.chave];
const saida = String($json.stderr || $json.stdout || $json.error?.message || $json.error || '').slice(-1500);
return { json: { ok, aviso: ok
  ? `↩️ Configuração normal restaurada em ${esc(d.resumo)}.`
  : `❌ Falhou ao desfazer em ${esc(d.resumo)}.\n<pre>${esc(saida)}</pre>` } };
